export const impostorGlyphs=Object.freeze(Object.fromEntries([["wizard",61440],["tomb",61443],["routes",61446],["paw",61449],["night",61452],["music",61455],["masks",61458],["devil",61461],["cry",61464],["crown",61467],["cross",61470],["candle",61473]].map(([e,r])=>[e,Object.freeze(Array.from({length:3},(e,o)=>String.fromCodePoint(r+o)))])));export function chooseImpostorGlyph(e,r=Math.random,o=null){const t=impostorGlyphs[e];if(!t)return null;const n=[0,1,2].filter(e=>e!==o),s=n[Math.floor(r()*n.length)];return Object.freeze({index:s,glyph:t[s]})}
